using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Threading;
using System.Xml.Linq;

namespace XmlA1 {
 public sealed class ScienceRecord {
  public string Key="",Status="",Code="",Message="",Protocol="",ResponsePath="";public DateTime At;public bool Queued;
  public bool Registered{get{return Status=="Registrada"||Status=="Sem vínculo"||Status=="Duplicidade";}}
  public bool CanCheckXml{get{return Registered||Code=="596";}}
 }
 public sealed class ScienceState {
  public bool Enabled;public DateTime Consent,Next;public List<ScienceRecord> Records=new List<ScienceRecord>();
 }
 /// <summary>Persiste autorização e tentativas antes da transmissão, evitando reenvio incerto.</summary>
 public sealed class ScienceStore {
  readonly string folder,rootName;public ScienceStore(string path=null,string rootName="ciencia"){this.rootName=rootName;folder=path??Path.Combine(System.Environment.GetFolderPath(System.Environment.SpecialFolder.LocalApplicationData),"XML-A1","ciencia");Directory.CreateDirectory(folder);}
  string PathFor(string c,int e){return Path.Combine(folder,Rules.Cnpj(c)+"_"+e+".xml");}
  public FileStream Lock(string c,int e){try{return new FileStream(PathFor(c,e)+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);}catch(IOException){throw new InvalidOperationException("A ciência deste CNPJ está em processamento em outra janela.");}}
  public ScienceState Load(string c,int e){var s=new ScienceState();if(!File.Exists(PathFor(c,e)))return s;try{var root=Rules.Xml(File.ReadAllBytes(PathFor(c,e))).Root;if(root.Name!=rootName)throw new InvalidDataException("Formato inválido.");s.Enabled=(bool?)root.Attribute("ativa")??false;s.Consent=Date((string)root.Attribute("autorizada"));s.Next=Date((string)root.Attribute("proxima"));var seen=new HashSet<string>();foreach(var x in root.Elements("envio")){string key=(string)x.Attribute("chave");if(!Rules.Key(key)||!seen.Add(key))throw new InvalidDataException("Chave inválida ou duplicada.");s.Records.Add(new ScienceRecord{Key=key,Status=(string)x.Attribute("situacao")??"Incerta",Code=(string)x.Attribute("codigo")??"",Protocol=(string)x.Attribute("protocolo")??"",ResponsePath=(string)x.Attribute("resposta")??"",Queued=(bool?)x.Attribute("naFila")??false,At=Date((string)x.Attribute("data")),Message=x.Value});}return s;}catch(Exception ex){throw new InvalidDataException("Histórico de ciência inválido; preserve o arquivo para recuperação.",ex);}}
  static DateTime Date(string value){return DateTime.Parse(value??DateTime.MinValue.ToString("o"),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind);}
  public void Save(string c,int e,ScienceState s){var xml=new XDocument(new XElement(rootName,new XAttribute("ativa",s.Enabled),new XAttribute("autorizada",s.Consent.ToString("o")),new XAttribute("proxima",s.Next.ToString("o")),s.Records.Select(r=>new XElement("envio",new XAttribute("chave",r.Key),new XAttribute("situacao",r.Status),new XAttribute("codigo",r.Code),new XAttribute("protocolo",r.Protocol),new XAttribute("resposta",r.ResponsePath),new XAttribute("naFila",r.Queued),new XAttribute("data",r.At.ToString("o")),r.Message))));Rules.WriteAtomic(PathFor(c,e),Rules.Utf8(xml));}
  public void Enable(string c,int e,bool enabled){using(Lock(c,e)){var s=Load(c,e);s.Enabled=enabled;if(enabled)s.Consent=DateTime.UtcNow;Save(c,e,s);}}
 }
 /// <summary>Envia somente ciência 210210 autorizada; 596 não é substituído por confirmação.</summary>
 public sealed class AutoScienceRunner {
  readonly StateStore states;readonly ScienceStore store;readonly KeyQueueStore queues;readonly XmlLibrary lib;readonly ISefaz client;readonly Action<string> log;readonly Func<DateTime> now;
  public AutoScienceRunner(StateStore states,ScienceStore store,KeyQueueStore queues,XmlLibrary lib,ISefaz client,Action<string> log,Func<DateTime> clock=null){this.states=states;this.store=store;this.queues=queues;this.lib=lib;this.client=client;this.log=log??delegate{};now=clock??(()=>DateTime.UtcNow);}
  public static bool Eligible(DocItem item,string cnpj,IEnumerable<DocItem> docs){return item.Category=="Resumos"&&item.NoteSituation=="1"&&Rules.Key(item.Key)&&!String.IsNullOrEmpty(item.Cnpj)&&item.Cnpj!=cnpj&&item.Key.Substring(6,14)==item.Cnpj.PadLeft(14,'0')&&!docs.Any(d=>d.Key==item.Key&&(d.Category=="Recebidas"||d.Category=="Emitidas"||d.Category=="Outras autorizadas"||(d.Category=="Resumos"&&(d.NoteSituation=="2"||d.NoteSituation=="3"))||(d.Category=="Eventos"&&new[]{"110111","210200","210210","210220","210240"}.Contains(d.EventType))));}
  public static ScienceRecord Parse(byte[] bytes,string cnpj,int env,string key){return ParseEvent(bytes,cnpj,env,key,"210210");}
  public static ScienceRecord ParseEvent(byte[] bytes,string cnpj,int env,string key,string eventType){XNamespace n=Rules.NfeNs;var x=Rules.Xml(bytes);var batch=x.Descendants(n+"retEnvEvento").SingleOrDefault();if(batch==null||Rules.Child(batch,"tpAmb")!=env.ToString()||Rules.Child(batch,"cStat")!="128")throw new InvalidDataException("Retorno da SEFAZ sem lote de eventos processado no ambiente solicitado.");var info=batch.Descendants(n+"retEvento").Single().Element(n+"infEvento");if(info==null)throw new InvalidDataException("Retorno sem resultado do evento.");string code=Rules.Child(info,"cStat");var r=new ScienceRecord{Key=key,Code=code,Message=Rules.Child(info,"xMotivo"),Protocol=Rules.Child(info,"nProt"),Status="Rejeitada"};if(new[]{"135","136","573"}.Contains(code)){string recipient=Rules.Child(info,"CNPJDest");if(Rules.Child(info,"tpAmb")!=env.ToString()||Rules.Child(info,"chNFe")!=key||Rules.Child(info,"tpEvento")!=eventType||Rules.Child(info,"nSeqEvento")!="1"||(recipient!=""&&recipient!=cnpj))throw new InvalidDataException("Retorno não corresponde à chave, evento, empresa ou ambiente solicitado.");if((code=="135"||code=="136")&&r.Protocol=="")throw new InvalidDataException("Evento sem protocolo de registro.");r.Status=code=="135"?"Registrada":code=="136"?"Sem vínculo":"Duplicidade";}return r;}
  void QueueXml(ScienceRecord r,int uf){if(!r.CanCheckXml||r.Queued)return;using(queues.Lock(lib.Cnpj,lib.Environment)){var q=queues.Load(lib.Cnpj,lib.Environment);q.Add(new[]{r.Key});var job=q.Jobs.Single(j=>j.Key==r.Key);if(job.Status!="Baixada"&&job.Status!="Já disponível"){job.Status="Pendente";job.ScienceCode=r.Code;job.AwaitXml=q.DownloadAll||r.Registered;job.NotBefore=r.Registered?r.At.AddHours(1):now();job.Updated=now();job.Message=r.Registered?"Ciência "+r.Code+"; aguardando XML completo da SEFAZ.":"Ciência rejeitada (596); verificar XML já liberado, sem enviar outro evento.";q.Uf=uf;q.AutoContinue=true;var next=q.Jobs.Where(j=>j.Status=="Pendente").Select(j=>j.NotBefore).Min();var allowed=KeyBatchRunner.AllowedAfter(states.Load(lib.Cnpj,lib.Environment),now());q.Next=next>allowed?next:allowed;}queues.Save(lib.Cnpj,lib.Environment,q);}r.Queued=true;}
  public int ScheduleDownloads(int uf,CancellationToken token){if(uf==0)return 0;using(store.Lock(lib.Cnpj,lib.Environment)){var s=store.Load(lib.Cnpj,lib.Environment);int count=0;foreach(var r in s.Records.Where(r=>r.CanCheckXml&&!r.Queued).ToList()){token.ThrowIfCancellationRequested();QueueXml(r,uf);store.Save(lib.Cnpj,lib.Environment,s);count++;}return count;}}
  void RecoverReply(ScienceState s,string key){if(s.Records.Any(record=>record.Key==key))return;string path=Path.Combine(lib.Folder,"Manifestacoes",key+"_ciencia_resposta.xml");if(!File.Exists(path))return;ScienceRecord r;try{r=Parse(File.ReadAllBytes(path),lib.Cnpj,lib.Environment,key);}catch{r=new ScienceRecord{Key=key,Status="Incerta",Message="Resposta anterior encontrada; confira o arquivo antes de reenviar."};}r.At=now();r.ResponsePath=path;s.Records.Add(r);store.Save(lib.Cnpj,lib.Environment,s);}
  ScienceRecord Send(ScienceState s,DocItem item,int uf,CancellationToken token){token.ThrowIfCancellationRequested();if(!Eligible(item,lib.Cnpj,lib.List()))throw new InvalidOperationException("Este resumo não é elegível para ciência: pode estar cancelado, já manifestado ou possuir XML completo.");if(uf==0)throw new InvalidOperationException("Selecione a UF para buscar o XML após a ciência.");
   RecoverReply(s,item.Key);var previous=s.Records.FirstOrDefault(r=>r.Key==item.Key);if(previous!=null){if(previous.CanCheckXml){QueueXml(previous,uf);store.Save(lib.Cnpj,lib.Environment,s);return previous;}throw new InvalidOperationException("Há um envio anterior "+previous.Status+" para esta chave. Confira o histórico em Manifestacoes antes de tentar novamente.");}
   var record=new ScienceRecord{Key=item.Key,At=now(),Status="Incerta",Message="Envio iniciado. Se houver interrupção, confira o retorno; o evento não será repetido automaticamente."};s.Records.Add(record);store.Save(lib.Cnpj,lib.Environment,s);
   using(states.Lock(lib.Cnpj,lib.Environment)){try{if(states.Load(lib.Cnpj,lib.Environment).AllAfter>now())throw new InvalidOperationException("Comunicação pausada para este CNPJ.");var transport=client as SefazClient;if(transport!=null)transport.ScienceRequest=bytes=>Rules.WriteAtomic(Path.Combine(lib.Folder,"Manifestacoes",item.Key+"_ciencia_pedido.xml"),bytes);byte[] response;try{response=client.Science(lib.Cnpj,lib.Environment,item.Key,token);}finally{if(transport!=null)transport.ScienceRequest=null;}record.ResponsePath=Path.Combine(lib.Folder,"Manifestacoes",item.Key+"_ciencia_resposta.xml");Rules.WriteAtomic(record.ResponsePath,response);var parsed=Parse(response,lib.Cnpj,lib.Environment,item.Key);record.Status=parsed.Status;record.Code=parsed.Code;record.Message=parsed.Message;record.Protocol=parsed.Protocol;store.Save(lib.Cnpj,lib.Environment,s);}catch(Exception ex){record.Message="Resultado incerto: "+ex.Message;s.Enabled=false;store.Save(lib.Cnpj,lib.Environment,s);throw;}}
   QueueXml(record,uf);store.Save(lib.Cnpj,lib.Environment,s);log("Ciência "+record.Key+": "+record.Status+" ("+record.Code+"). "+record.Message);return record;
  }
  public ScienceRecord Manual(DocItem item,int uf,CancellationToken token){using(store.Lock(lib.Cnpj,lib.Environment)){var s=store.Load(lib.Cnpj,lib.Environment);if(states.Load(lib.Cnpj,lib.Environment).AllAfter>now())throw new InvalidOperationException("Aguarde o fim da pausa de comunicação antes de registrar ciência.");return Send(s,item,uf,token);}}
  public int Run(int uf,CancellationToken token){return RunScope(uf,token,null);}
  public int RunForQueue(int uf,CancellationToken token){HashSet<string> keys;using(queues.Lock(lib.Cnpj,lib.Environment)){var q=queues.Load(lib.Cnpj,lib.Environment);if(q.ConfirmForDownload||!q.ScienceForDownload||q.ScienceConsent==DateTime.MinValue)return 0;keys=new HashSet<string>(q.Jobs.Where(j=>j.Status=="Pendente").Select(j=>j.Key));}if(keys.Count==0)return 0;try{int count=RunScope(uf,token,keys);var state=store.Load(lib.Cnpj,lib.Environment);if(state.Records.Any(r=>keys.Contains(r.Key)&&!r.CanCheckXml))PauseQueueScience();return count;}catch{PauseQueueScience();throw;}}
  void PauseQueueScience(){using(queues.Lock(lib.Cnpj,lib.Environment)){var q=queues.Load(lib.Cnpj,lib.Environment);q.ScienceForDownload=false;queues.Save(lib.Cnpj,lib.Environment,q);}}
  int RunScope(int uf,CancellationToken token,HashSet<string> keys){using(store.Lock(lib.Cnpj,lib.Environment)){var s=store.Load(lib.Cnpj,lib.Environment);if((keys==null&&!s.Enabled)||s.Next>now()||states.Load(lib.Cnpj,lib.Environment).AllAfter>now())return 0;if(uf==0)throw new InvalidOperationException("Selecione a UF para ativar a ciência automática.");int sent=0;var docs=lib.List();if(keys!=null)docs=docs.Where(d=>keys.Contains(d.Key)).ToList();else{var q=queues.Load(lib.Cnpj,lib.Environment);if(q.ConfirmForDownload&&q.ConfirmationConsent!=DateTime.MinValue){var reserved=new HashSet<string>(q.Jobs.Where(j=>j.UserSupplied).Select(j=>j.Key));docs=docs.Where(d=>!reserved.Contains(d.Key)).ToList();}}
   // Older manual replies must never lead to a second automatic submission.
   foreach(var item in docs.Where(d=>d.Category=="Resumos").GroupBy(d=>d.Key).Select(g=>g.First()))RecoverReply(s,item.Key);
   foreach(var r in s.Records.Where(r=>r.CanCheckXml&&!r.Queued).ToList()){token.ThrowIfCancellationRequested();QueueXml(r,uf);store.Save(lib.Cnpj,lib.Environment,s);}
   foreach(var item in docs.Where(d=>Eligible(d,lib.Cnpj,docs)).GroupBy(d=>d.Key).Select(g=>g.First())){if(s.Records.Any(r=>r.Key==item.Key))continue;token.ThrowIfCancellationRequested();var result=Send(s,item,uf,token);sent++;if(!result.CanCheckXml){s.Enabled=false;log("Ciência automática pausada após rejeição. Confira o retorno em Manifestacoes.");break;}if(result.Code=="596")log("Prazo de ciência encerrado. A chave será consultada para verificar XML já liberado; as outras notas continuarão.");if(sent>=20)break;}
   if(sent>0)s.Next=now().AddMinutes(5);store.Save(lib.Cnpj,lib.Environment,s);return sent;
  }}
 }
}
